% SPDX-License-Identifier: EUPL-1.2
:- module(m__eu_dsa_art_14_terms_and_conditions_order_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

citation(eu_reg_2022_2065_art_14_1, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 14(1), content, language and availability of terms and conditions', ref - 'CELEX 32022R2065, unit parag_014.001, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Providers of intermediary services shall include information on any restrictions that they impose in relation to the use of their service in respect of information provided by the recipients of the service, in their terms and conditions. That information shall include information on any policies, procedures, measures and tools used for the purpose of content moderation, including algorithmic decision-making and human review, as well as the rules of procedure of their internal complaint handling system. It shall be set out in clear, plain, intelligible, user-friendly and unambiguous language, and shall be publicly available in an easily accessible and machine-readable format.']).
citation(eu_reg_2022_2065_art_14_2, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 14(2), duty to inform recipients of a significant change to the terms and conditions', ref - 'CELEX 32022R2065, unit parag_014.002, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Providers of intermediary services shall inform the recipients of the service of any significant change to the terms and conditions.']).
citation(eu_reg_2022_2065_art_14_3, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 14(3), explanation of conditions and restrictions in a way minors can understand', ref - 'CELEX 32022R2065, unit parag_014.003, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Where an intermediary service is primarily directed at minors or is predominantly used by them, the provider of that intermediary service shall explain the conditions for, and any restrictions on, the use of the service in a way that minors can understand.']).
citation(eu_reg_2022_2065_art_14_4, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 14(4), diligent, objective and proportionate application and enforcement of restrictions with due regard to rights', ref - 'CELEX 32022R2065, unit parag_014.004, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Providers of intermediary services shall act in a diligent, objective and proportionate manner in applying and enforcing the restrictions referred to in paragraph 1, with due regard to the rights and legitimate interests of all parties involved, including the fundamental rights of the recipients of the service, such as the freedom of expression, freedom and pluralism of the media, and other fundamental rights and freedoms as enshrined in the Charter.']).
citation(eu_reg_2022_2065_art_14_5, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 14(5), summary of the terms and conditions by very large online platforms and very large online search engines', ref - 'CELEX 32022R2065, unit parag_014.005, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Providers of very large online platforms and of very large online search engines shall provide recipients of services with a concise, easily-accessible and machine-readable summary of the terms and conditions, including the available remedies and redress mechanisms, in clear and unambiguous language.']).
citation(eu_reg_2022_2065_art_14_6, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 14(6), publication of the terms and conditions in the official languages of the Member States of service', ref - 'CELEX 32022R2065, unit parag_014.006, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Very large online platforms and very large online search engines within the meaning of Article 33 shall publish their terms and conditions in the official languages of all the Member States in which they offer their services.']).
citation(commission_vlop_or_vlose_designation_decision, [label - 'European Commission decision under Regulation (EU) 2022/2065 Art 33 designating a very large online platform or a very large online search engine', ref - 'https://digital-strategy.ec.europa.eu/en/policies/list-designated-vlops-and-vloses']).
citation(eu_reg_2022_2065_chapter_3_section_1, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Chapter III, title of Section 1 (Articles 11 to 15)', ref - 'CELEX 32022R2065, pinned extract sources/32022R2065-chapter-iii-sections.txt, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Provisions applicable to all providers of intermediary services']).
citation(eu_reg_2022_2065_chapter_3_section_3, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Chapter III, title of Section 3 (Articles 19 to 28)', ref - 'CELEX 32022R2065, pinned extract sources/32022R2065-chapter-iii-sections.txt, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'Additional provisions applicable to providers of online platforms']).
citation(eu_reg_2022_2065_art_19_1, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 19(1), exclusion of micro and small enterprises from Section 3 of Chapter III', ref - 'CELEX 32022R2065, unit parag_019.001, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'This Section, with the exception of Article 24(3) thereof, shall not apply to providers of online platforms that qualify as micro or small enterprises as defined in Recommendation 2003/361/EC.']).
citation(eu_reg_2022_2065_art_19_2, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 19(2), derogation for designated very large online platforms', ref - 'CELEX 32022R2065, unit parag_019.002, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'By derogation from paragraph 1 of this Article, this Section shall apply to providers of online platforms that have been designated as very large online platforms in accordance with Article 33, irrespective of whether they qualify as micro or small enterprises.']).
citation(eu_reg_2022_2065_art_3_b, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 3, point (b), definition of recipient of the service', ref - 'CELEX 32022R2065, unit point_003_b, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'means any natural or legal person who uses an intermediary service, in particular for the purposes of seeking information or making it accessible;']).
citation(eu_reg_2022_2065_art_3_g, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 3, point (g), definition of intermediary service', ref - 'CELEX 32022R2065, unit point_003_g, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'means one of the following information society services:']).
citation(eu_reg_2022_2065_art_3_i, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 3, point (i), definition of online platform', ref - 'CELEX 32022R2065, unit point_003_i, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'means a hosting service that, at the request of a recipient of the service, stores and disseminates information to the public']).
citation(eu_reg_2022_2065_art_3_j, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 3, point (j), definition of online search engine', ref - 'CELEX 32022R2065, unit point_003_j, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'means an intermediary service that allows users to input queries in order to perform searches of, in principle, all websites, or all websites in a particular language']).
citation(eu_reg_2022_2065_art_3_t, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 3, point (t), definition of content moderation', ref - 'CELEX 32022R2065, unit point_003_t, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'means the activities, whether automated or not, undertaken by providers of intermediary services, that are aimed, in particular, at detecting, identifying and addressing illegal content or information incompatible with their terms and conditions, provided by recipients of the service']).
citation(eu_reg_2022_2065_art_3_u, [label - 'Regulation (EU) 2022/2065 (Digital Services Act) Art 3, point (u), definition of terms and conditions', ref - 'CELEX 32022R2065, unit point_003_u, OJ L 277, 27.10.2022, https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2065', verbatim - 'means all clauses, irrespective of their name or form, which govern the contractual relationship between the provider of intermediary services and the recipients of the service;']).

implements(Key) :-
    citation(Key, _).

test(every_answer_key_is_recorded) :-
    implements(eu_reg_2022_2065_art_14_1),
    implements(eu_reg_2022_2065_art_14_2),
    implements(eu_reg_2022_2065_art_14_3),
    implements(eu_reg_2022_2065_art_14_4),
    implements(eu_reg_2022_2065_art_14_5),
    implements(eu_reg_2022_2065_art_14_6).
test(the_referral_target_is_recorded) :-
    implements(commission_vlop_or_vlose_designation_decision).

test(a_shortened_key_is_not_recorded, fail) :-
    implements(art_14_1).
